<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Categories</h1></div><div class="row"><div class="col-lg-4"><?php if(can('categories.create')):?><div class="card"><div class="card-header"><h5 class="card-title mb-0">Add Category</h5></div><div class="card-body"><form method="post" action="<?=url('categories')?>"><?=csrf_field()?><input class="form-control mb-2" name="name" placeholder="Name" required><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><input class="form-control mb-2" name="icon" value="tag" placeholder="Icon"><input class="form-control mb-2" type="color" name="color" value="#3b7ddd"><select class="form-select mb-3" name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select><button class="btn btn-primary">Create</button></form></div></div><?php endif;?></div><div class="col-lg-8"><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Name</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><i data-feather="<?=e($r['icon'])?>"></i> <?=e($r['name'])?></td><td><span class="badge bg-<?=($r['status']==='active'?'success':'secondary')?>"><?=e($r['status'])?></span></td><td class="text-end"><form class="d-inline" method="post" action="<?=url('categories/'.$r['id'].'/delete')?>" onsubmit="return confirm('Delete this category?');"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>